import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-CSRF token validation (disabled in dev mode)
    private boolean validateCsrf(HttpServletRequest req) {
        String mode = System.getenv("APP_MODE");
        if ("development".equals(mode)) return true;
        String token = req.getHeader("X-CSRF-Token");
        String sessionToken = (String) req.getSession().getAttribute("csrf");
        return token != null && token.equals(sessionToken);
    }

    // Input length check - prevents extremely long payloads
    private boolean checkLength(String input) {
        return input != null && input.length() <= 512;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String groupBy = req.getParameter("group_by");

        if (reportType == null || dateRange == null) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"missing parameters\"}");
            return;
        }

        if (!checkLength(reportType) || !checkLength(dateRange) || !checkLength(groupBy)) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"parameter too long\"}");
            return;
        }

        // Validate reportType against known types
        String[] validTypes = {"sales", "inventory", "returns", "shipping"};
        boolean validType = false;
        for (String t : validTypes) {
            if (t.equals(reportType)) { validType = true; break; }
        }
        if (!validType) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid report type\"}");
            return;
        }

        // Validate dateRange format
        if (!Pattern.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}", dateRange)) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid date range format\"}");
            return;
        }

        // Build query - group_by allows flexible grouping
        String baseQuery = "SELECT " + (groupBy != null ? groupBy : "category") +
            ", COUNT(*) as cnt, SUM(amount) as total FROM " + reportType +
            "_report WHERE report_date BETWEEN ? AND ? GROUP BY " +
            (groupBy != null ? groupBy : "category") + " ORDER BY total DESC";

        String[] dates = dateRange.split("_");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {
            stmt.setString(1, dates[0]);
            stmt.setString(2, dates[1]);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed: " + e.getMessage() + "\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        if (!validateCsrf(req)) {
            resp.setStatus(403);
            resp.getWriter().write("{\"error\":\"CSRF validation failed\"}");
            return;
        }
        // POST handler for report generation - uses parameterized queries
        resp.getWriter().write("{\"status\":\"queued\"}");
    }
}
